styles.css:
position: relative;
overflow: hidden;
--ls-card-feature-border-active:var(--wp--custom--color--link--accent);
--ls-card-feature-icon-border-active:var(--wp--custom--color--icon--background);
--ls-card-feature-shadow-active:var(--wp--custom--shadow--card--hover);
--ls-card-feature-icon-shadow-active:var(--wp--custom--shadow--elevation--300), 0 22px 44px -22px color-mix(in srgb, var(--wp--custom--color--icon--background) 76%, transparent);
--ls-card-feature-lift:var(--wp--custom--animation--lift--lg);

& .ls-card-feature__content {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
	gap: var(--wp--preset--spacing--20);
}

& .ls-card-feature__cta {
	margin-top: auto;
	margin-bottom: 0;
}

& .ls-card__icon-shell {
	align-self: flex-start;
}

& .ls-card-feature__link::before {
	content: "";
	position: absolute;
	inset: 0;
}

& .ls-card-feature__link:focus-visible {
	outline: 2px solid var(--wp--custom--color--focus--ring);
	outline-offset: 2px;
}
